    v.push(("files", Regex::new(r"[\w\-. ]+?\.(?:txt|pdf|doc|xls|csv|json|xml|js|py|rb|sh|bat|ps1|exe|dll|zip|tar|gz|rar|7z|jpg|jpeg|png|gif|bmp|log|ini|cfg|conf|yaml|db|sql|bak|old|mdb|sys)").unwrap()));
    // bitcoin: [13][base58]{25,34} total 26-35, base58 excludes 0,O,I,l
    v.push(("bitcoin_wallet", Regex::new(r"\b[13][1-9A-HJ-NP-Za-km-z]{25,34}\b").unwrap()));
    // aws: aws_access_key_id or secret, = with optional spaces, value 20-40 chars of allowed set
    v.push(("aws_keys", Regex::new(r"aws_(?:access_key_id|secret_access_key)\s*=\s*[A-Za-z0-9/+=.,@_\-]{20,40}").unwrap()));
    // google: strict "private_key_id": "40chars"
    v.push(("google", Regex::new(r#""private_key_id": "[A-Za-z0-9\-_/.+=]{40}""#).unwrap()));
    // dns: never matches (implement as impossible pattern)
    v.push(("dns", Regex::new(r"(?!)").unwrap()));
    // social
    v.push(("social_security", Regex::new(r"\b\d{3}-\d{2}-\d{4}\b").unwrap()));
    v
}

fn extract_url_match(m: &str) -> String {
    // Trim trailing .,;,()[]{}"'<> as observed (but keep !?*= etc.)
    let mut s = m.to_string();
    while s.ends_with('.') || s.ends_with(',') || s.ends_with(';') || s.ends_with(')') || s.ends_with(']') || s.ends_with('}') || s.ends_with('"') || s.ends_with('\'') || s.ends_with('>') || s.ends_with('<') || s.ends_with('(') || s.ends_with('[') || s.ends_with('{') {
        s.pop();
    }
    // Also trim trailing :? Already stopped at :, but if match ends with : (e.g., https://example.com:), trim?
    while s.ends_with(':') || s.ends_with(';') || s.ends_with(',') || s.ends_with('.') {
        s.pop();
    }
    s
}

