fn format_plain(identifier: &str, content: &str, filename: Option<&str>, line_num: Option<usize>, hide: bool, display: bool, line_flag: bool) -> String {
    // filename: Some(path) if display, else None. For stdin with display, filename is Some("") (empty).
    // line_num: Some(n) if line_flag, else None
    // hide: if true, omit identifier
    // display: if true, include file part
    // line_flag: if true, include line part
    // Logic:
    // without display, without line: "[id: ]content"
    // without display, with line: "[id, ]content, line: N"
    // with display, without line: "[id, ]file: <filename> content"
    // with display, with line: "[id, ]file: <filename> content, line: N"
    // where [id, ] is "id, " if not hide (for line/display cases) or "id: " if not hide and no line/display? Actually for plain without line/display, it's "id: "
    // For line/display cases, identifier without colon, with comma: "id, "
    if display {
        let fname = filename.unwrap_or("");
        if line_flag {
            let ln = line_num.unwrap();
            if hide {
                format!("file: {} {}, line: {}", fname, content, ln)
            } else {
                format!("{}, file: {} {}, line: {}", identifier, fname, content, ln)
            }
        } else {
            if hide {
                format!("file: {} {}", fname, content)
            } else {
                format!("{}, file: {} {}", identifier, fname, content)
            }
        }
    } else {
        if line_flag {
            let ln = line_num.unwrap();
            if hide {
                format!("{}, line: {}", content, ln)
            } else {
                format!("{}, {}, line: {}", identifier, content, ln)
            }
        } else {
            if hide {
                format!("{}", content)
            } else {
                format!("{}: {}", identifier, content)
            }
        }
    }
}

fn csv_header(hide: bool, display: bool, line_flag: bool) -> String {
    let mut parts: Vec<&str> = Vec::new();
    if !hide {
        parts.push("content_type");
    }
    if display {
        parts.push("file");
    }
    if line_flag {
        parts.push("line");
    }
    parts.push("data");
    parts.join(", ")
}

fn csv_row(identifier: &str, content: &str, filename: Option<&str>, line_num: Option<usize>, hide: bool, display: bool, line_flag: bool) -> String {
    let mut parts: Vec<String> = Vec::new();
    if !hide {
        parts.push(identifier.to_string());
    }
    if display {
        parts.push(filename.unwrap_or("").to_string());
    }
    if line_flag {
        parts.push(line_num.unwrap().to_string());
    }
    parts.push(content.to_string());
    parts.join(", ")
}

